<?php

declare(strict_types=1);

namespace App\Tests\Api;

use App\Tests\Support\ContractDocument;
use App\Tests\Support\GeneratedSpec;
use PHPUnit\Framework\Attributes\Test;

/**
 * B-3's phase-2 half — the generated artifact, and API-10a's three outcomes.
 *
 * The spec is regenerated by running the command rather than by reaching into
 * the factory, because **NO ARTIFACT is one of the three outcomes** and a
 * generator that cannot produce a document has to be able to say so here.
 */
final class OpenApiContractTest extends ApiTestCase
{
    /**
     * **What "write" means in this file, on both sides of every comparison.** An
     * operation is a write if its HTTP method is one of these: on the spec side
     * the method is the path item's key, on the document side it is §4.2's
     * `Method` cell for the row with the same operationId. One constant, so the
     * two sides cannot be derived differently. `PUT` is listed although API-5
     * removes it (`a3fb961` checks that): a `PUT` that appeared would be a write,
     * and a definition that left it out would let it through every check here.
     */
    private const WRITE_METHODS = ['POST', 'PUT', 'PATCH', 'DELETE'];

    /** @return array<string, mixed> */
    private function regenerate(): array
    {
        return GeneratedSpec::regenerate(self::bootedKernel());
    }

    private static function bootedKernel(): \Symfony\Component\HttpKernel\KernelInterface
    {
        return self::$kernel ?? throw new \LogicException('The kernel is booted in setUp().');
    }

    /**
     * API-10a. The outcome today is **VACUOUS** and this test says so out loud:
     * the spec declares fewer write operations than §4.2 does, so the `id`
     * assertion below is real but the gate is not passed. Owner decision (d),
     * 2026-09-14, rules VACUOUS M0-b's outcome — **never recorded as a pass** —
     * together with C7's equality, which is
     * {@see self::theSpecsWriteOperationsAreExactlySection151sBuiltWriteRows()}.
     *
     * When the last §4.2 row is built (M4), the counts converge and this test
     * goes red — which is deliberate. It is the thing that forces somebody to
     * change the assertion to PASS on purpose rather than discovering that a
     * partially authored spec had been reported as green.
     *
     * **What the old `AUTHORED_WRITE_OPERATIONS = 15` protected, and where each
     * property now lives (C7, 2026-09-15):**
     *  - *the floor* — deleting the `ApiResource` classes turns this file red
     *    (API-10a's second mutation). With the document present, the C7
     *    equality is red for every built write operation that vanishes, by
     *    name. On a clean checkout the equality has no second side, so the
     *    assertion below that the spec declares at least one write runs first
     *    on every checkout; the exact shipped set is held without the document
     *    by `AuthOperationContractTest::theShippedSurfaceIsExactlyTheOperationsThisWaveHasPinned`.
     *  - *the ceiling that forces a rewrite* — here, unchanged in meaning: the
     *    spec's write count must stay **below** §4.2's.
     *  - *both sides moving together* — the constant had to be raised by hand
     *    whenever a write operation shipped, and nothing caught forgetting. The
     *    equality replaces that hand step with §15.1, which is re-derived
     *    whenever a row ships and which this file now reads.
     */
    #[Test]
    public function theApi10aOutcomeIsVacuousAndIsNotRecordedAsAPass(): void
    {
        $spec = $this->regenerate();
        $generated = $this->writeOperationIds($spec);

        self::assertNotSame([], $generated, 'The generated spec declares no write operation, so a VACUOUS outcome here would be empty against the contract.');

        if (!ContractDocument::isAvailable()) {
            self::markTestSkipped('docs/API.md is gitignored and absent, so the VACUOUS comparison has no second side. The non-empty check above still ran.');
        }

        $documented = array_filter(
            ContractDocument::operationRows(),
            static fn (array $row): bool => \in_array($row['method'], self::WRITE_METHODS, true),
        );

        self::assertGreaterThan(
            \count($generated),
            \count($documented),
            \sprintf(
                'The spec now declares as many write operations as §4.2 does (%d). The API-10a outcome has moved from '
                .'VACUOUS to PASS/FAIL and this test must be rewritten to assert the PASS branch.',
                \count($documented),
            ),
        );
    }

    /**
     * **C7 (owner decision (d)): the generated spec's write operations are
     * exactly §15.1's built write rows** — an equality, red on drift in either
     * direction, and naming the operation that drifted.
     *
     * Both sides are sets of operationIds, and "write" is {@see self::WRITE_METHODS}
     * on both:
     *  - **spec side** — every operation under `paths` whose method key is a
     *    write method, by its `operationId`;
     *  - **document side** — every §15.1 row whose status is `built`
     *    (`ContractDocument::buildStatuses()`), kept if §4.2's `Method` cell for
     *    that operationId is a write method. A built row with no §4.2 row has no
     *    method to classify it by and is reported, never dropped.
     *
     * Controls, inside this method: §15.1 yields rows, some built; both sets
     * are non-empty; and the comparison is shown to name a planted extra name on
     * either side and a removed real name on either side before it is trusted.
     *
     * Mutations (C7, 2026-09-15, `docs/session10/progress-C4C7.md`): (a) a
     * throwaway write operation added to a resource (`backend/var/cache/test`
     * deleted before and after — Rule 17) → red naming it as missing from
     * §15.1; (b) in a scratch copy of `docs/API.md`, a §15.1 row flipped to
     * `built` for a write with no operation → red naming it as missing from the
     * spec. Both reverted; `docs/API.md` restored byte-identical.
     *
     * **Writes only, by decision (d) — reads are out of scope** (V1-R-19, recorded
     * 2026-09-16, V4 B4e): a §15.1 read row flipped to `built` with no operation,
     * or a shipped read whose §15.1 row still says `unbuilt`, stays green here
     * (C7's progress note: "read flip stays green"). Owner: BE-LEAD. Trigger to
     * revisit: M4, where the whole contract closes — extend to reads then.
     */
    #[Test]
    public function theSpecsWriteOperationsAreExactlySection151sBuiltWriteRows(): void
    {
        $spec = $this->regenerate();
        $generated = $this->writeOperationIds($spec);

        self::assertNotSame([], $generated, 'The generated spec declares no write operation, so the equality below would have one empty side.');

        if (!ContractDocument::isAvailable()) {
            self::markTestSkipped('docs/API.md is gitignored and absent, so §15.1 is not there to compare the spec with.');
        }

        $contract = ContractDocument::operationRows();
        $statuses = ContractDocument::buildStatuses();

        self::assertNotSame([], $statuses, '§15.1 yielded no rows, so the document side would be empty.');
        self::assertContains('built', $statuses, '§15.1 marks nothing built, so the document side would be empty.');

        $unclassifiable = [];
        $documented = [];
        foreach (array_keys(array_filter($statuses, static fn (string $status): bool => 'built' === $status)) as $operationId) {
            if (!isset($contract[$operationId])) {
                $unclassifiable[] = $operationId;

                continue;
            }
            if (\in_array($contract[$operationId]['method'], self::WRITE_METHODS, true)) {
                $documented[] = $operationId;
            }
        }
        sort($documented);

        self::assertSame([], $unclassifiable, '§15.1 marks these built but §4.2 has no row for them, so their method is unknown.');
        self::assertNotSame([], $documented, '§15.1 marks no write row built, so the equality below would have one empty side.');

        // The comparison is shown to discriminate, in all four directions, before it is read.
        $planted = 'PlantedC7WriteOperation';
        self::assertSame(['missing from §15.1' => [$planted], 'missing from the spec' => []], self::writeDrift([...$generated, $planted], $generated));
        self::assertSame(['missing from §15.1' => [], 'missing from the spec' => [$planted]], self::writeDrift($generated, [...$generated, $planted]));
        self::assertSame(['missing from §15.1' => [], 'missing from the spec' => [$generated[0]]], self::writeDrift(\array_slice($generated, 1), $generated));
        self::assertSame(['missing from §15.1' => [$generated[0]], 'missing from the spec' => []], self::writeDrift($generated, \array_slice($generated, 1)));

        self::assertSame(
            ['missing from §15.1' => [], 'missing from the spec' => []],
            self::writeDrift($generated, $documented),
            'C7: the generated spec\'s write operations and §15.1\'s built write rows differ.',
        );
    }

    /**
     * @param list<string> $spec
     * @param list<string> $document
     *
     * @return array{'missing from §15.1': list<string>, 'missing from the spec': list<string>}
     */
    private static function writeDrift(array $spec, array $document): array
    {
        $extra = array_values(array_diff($spec, $document));
        $missing = array_values(array_diff($document, $spec));
        sort($extra);
        sort($missing);

        return ['missing from §15.1' => $extra, 'missing from the spec' => $missing];
    }

    /**
     * The write operations' ids, sorted, from the generated spec.
     *
     * @param array<string, mixed> $spec
     *
     * @return list<string>
     */
    private function writeOperationIds(array $spec): array
    {
        $ids = [];
        foreach ($this->writeOperations($spec) as $label => $operation) {
            $ids[] = \is_string($operation['operationId'] ?? null) ? $operation['operationId'] : '(no operationId) '.$label;
        }
        sort($ids);

        return $ids;
    }

    /**
     * The `id` assertion itself, which is what B-3's phase-2 check is for. It
     * resolves `$ref`s before inspecting: a schema-local scan misses an `id`
     * inside a referenced component, which is exactly where a nested write
     * would put one.
     *
     * **This proves B-3's declaration layer only** — that no request schema
     * *documents* an `id`. It cannot see whether a body carrying one is
     * accepted; that is `ItemWriteTest::aCreateCarryingAnIdIsRefused`, whose
     * docblock names the three layers and which one answers.
     *
     * Mutation (C5, 2026-09-14, `backend/var/cache/test` deleted before the
     * mutated run and before the revert run — Rule 17): `public ?string $id`
     * added to `CreateItemInput`, with `CreateItem`'s `allow_extra_attributes`
     * also removed → RED, `B-3: a write schema declares a row identifier.` with
     * `POST /api/v1/items application/json /id`. The runtime test stayed GREEN
     * in that same run — API Platform's own normaliser refuses the `id` first
     * (the re-run saw the same with the property alone). Revert: GREEN.
     */
    #[Test]
    public function noWriteSchemaDeclaresAnIdProperty(): void
    {
        $spec = $this->regenerate();
        $writes = $this->writeOperations($spec);

        self::assertNotSame([], $writes, 'No write operation was found, so the assertion below would be vacuous.');

        $inspected = 0;
        $offenders = [];

        foreach ($writes as $label => $operation) {
            foreach ($operation['requestBody']['content'] ?? [] as $mediaType => $content) {
                if (!isset($content['schema'])) {
                    continue;
                }

                ++$inspected;
                foreach ($this->propertyPaths($content['schema'], $spec) as $path) {
                    if (str_ends_with($path, '/id')) {
                        $offenders[] = $label.' '.$mediaType.' '.$path;
                    }
                }
            }
        }

        self::assertGreaterThan(0, $inspected, 'No request schema was inspected, so this check had no subject.');
        self::assertSame([], $offenders, 'B-3: a write schema declares a row identifier.');
    }

    /** API-9, as the artifact states it. */
    #[Test]
    public function everyWriteSchemaRefusesAdditionalProperties(): void
    {
        $spec = $this->regenerate();
        $checked = 0;

        foreach ($this->writeOperations($spec) as $label => $operation) {
            foreach ($operation['requestBody']['content'] ?? [] as $content) {
                $schema = $this->resolve($content['schema'] ?? [], $spec);
                ++$checked;
                self::assertFalse($schema['additionalProperties'] ?? true, $label.' accepts undeclared fields.');
            }
        }

        self::assertGreaterThan(0, $checked);
    }

    /** A `$ref` naming a component that does not exist is a spec that cannot be read. */
    #[Test]
    public function everyReferenceInTheSpecResolves(): void
    {
        $spec = $this->regenerate();

        $refs = [];
        array_walk_recursive($spec, static function (mixed $value, string|int $key) use (&$refs): void {
            if ('$ref' === $key && \is_string($value)) {
                $refs[] = $value;
            }
        });

        self::assertNotSame([], $refs);

        foreach (array_unique($refs) as $ref) {
            self::assertSame('#/components/schemas/', substr($ref, 0, 21), 'Unexpected reference form: '.$ref);
            self::assertArrayHasKey(substr($ref, 21), $spec['components']['schemas'], $ref.' names no component.');
        }
    }

    /** API-2 and API-3, as the artifact states them. */
    #[Test]
    public function theSpecIsMountedAtTheVersionedBasePathAndMentionsNoJsonLd(): void
    {
        $spec = $this->regenerate();

        self::assertNotSame([], $spec['paths']);
        foreach (array_keys($spec['paths']) as $path) {
            self::assertStringStartsWith(self::BASE.'/', (string) $path);
        }

        $encoded = json_encode($spec, \JSON_THROW_ON_ERROR);
        self::assertStringNotContainsString('application/ld+json', $encoded);
        self::assertStringNotContainsString('hydra', $encoded);
    }

    /**
     * API-O-33 option (a): the receipt's `received_by` is advertised as an
     * `ActorReference` **or null**, the same schema `PurchaseOrder.created_by`
     * carries. The column is nullable by design, so a spec that promised an
     * object would promise something the API does not always send.
     */
    #[Test]
    public function theReceiptReadSchemaAdvertisesTheReceiverAsNullableLikeTheCreator(): void
    {
        $spec = $this->regenerate();
        $nullableActor = ['anyOf' => [['$ref' => '#/components/schemas/ActorReference'], ['type' => 'null']]];

        self::assertSame($nullableActor, $spec['components']['schemas']['GoodsReceipt']['properties']['received_by'] ?? null);
        self::assertSame($nullableActor, $spec['components']['schemas']['PurchaseOrder']['properties']['created_by'] ?? null);
    }

    /**
     * §12.3 — every operation declares an explicit `operationId`, and no two share one.
     *
     * **The derivation check reads `api_`, not `_api_`** (V1-R-18, V4 B4b). API
     * Platform strips the leading underscore when it derives an `operationId` from an
     * operation name (`NormalizeOperationNameTrait`: `_api_/b4-plants/{id}_get` →
     * `api_b4-plants_id_get`), so `assertStringStartsNotWith('_api_', …)` could never
     * fail. Measured with a planted `App\` `Get` declared without `name:` or
     * `operationId` (Rule 17, cache deleted before and after): with `_api_` this method
     * stayed GREEN while `OperationIdTest` went red on `"api_b4-plants_id_get"`; with
     * `^_?api_` it goes RED naming `get /api/v1/b4-plants/{id}`.
     */
    #[Test]
    public function everyOperationIdIsExplicitAndUnique(): void
    {
        $spec = $this->regenerate();

        $ids = [];
        foreach ($spec['paths'] as $path => $methods) {
            foreach ($methods as $method => $operation) {
                self::assertArrayHasKey('operationId', $operation, $method.' '.$path);
                self::assertDoesNotMatchRegularExpression('/^_?api_/', $operation['operationId'], 'API Platform\'s derivation was not overridden on '.$method.' '.$path);
                $ids[] = $operation['operationId'];
            }
        }

        self::assertSame($ids, array_unique($ids));
    }

    /**
     * §3.3's phase-1 check, executed rather than described: the two ragged-row
     * guards, the extraction, and the assertion. Part (0b) is here because a
     * real defect walked through part (0a) — a gained cell and a lost trailing
     * pipe cancel exactly, leaving the field count unchanged.
     */
    #[Test]
    public function theContractDocumentDeclaresNoIdOnAnyWriteRow(): void
    {
        if (!ContractDocument::isAvailable()) {
            self::markTestSkipped('docs/API.md is gitignored and absent from this checkout. See the phase-2 report.');
        }

        $fieldCounts = [];
        $delimiterFaults = [];

        foreach (ContractDocument::lines() as $number => $line) {
            $pipes = substr_count($line, '|');
            if ($pipes <= 8) {
                continue;
            }

            $fieldCounts[] = $pipes + 1;

            if (!str_starts_with($line, '|')) {
                continue;
            }
            if (!str_ends_with(rtrim($line), '|')) {
                $delimiterFaults[] = 'line '.($number + 1).': row does not close with a pipe';
            } elseif (10 !== $pipes) {
                $delimiterFaults[] = 'line '.($number + 1).': wrong pipe count ('.$pipes.')';
            }
        }

        // (0a) one field count and nothing else.
        self::assertSame([11], array_values(array_unique($fieldCounts)));
        // (0b) delimiter integrity, on the literal bytes.
        self::assertSame([], $delimiterFaults);

        // (1) the extraction must be non-empty, and that is half the check.
        $writes = array_filter(
            ContractDocument::operationRows(),
            static fn (array $row): bool => \in_array($row['method'], self::WRITE_METHODS, true),
        );
        self::assertNotSame([], $writes);

        // (2) no write row accepts a field named `id`. `supplier_id` and
        // `role_id` are §3.1 case 1 and must NOT match.
        $offenders = [];
        foreach ($writes as $operationId => $row) {
            if (1 === preg_match('/`id`|\.id`/', $row['accepts'])) {
                $offenders[] = $operationId;
            }
        }

        self::assertSame([], $offenders);
    }

    /**
     * @param array<string, mixed> $spec
     *
     * @return array<string, array<string, mixed>>
     */
    private function writeOperations(array $spec): array
    {
        $writes = [];

        foreach ($spec['paths'] as $path => $methods) {
            foreach ($methods as $method => $operation) {
                if (\in_array(strtoupper((string) $method), self::WRITE_METHODS, true)) {
                    $writes[strtoupper((string) $method).' '.$path] = $operation;
                }
            }
        }

        return $writes;
    }

    /**
     * @param array<string, mixed> $schema
     * @param array<string, mixed> $spec
     *
     * @return array<string, mixed>
     */
    private function resolve(array $schema, array $spec): array
    {
        if (isset($schema['$ref']) && \is_string($schema['$ref'])) {
            $name = substr($schema['$ref'], 21);

            return $spec['components']['schemas'][$name] ?? [];
        }

        return $schema;
    }

    /**
     * Every property path a schema declares, with `$ref`s followed.
     *
     * @param array<string, mixed> $schema
     * @param array<string, mixed> $spec
     * @param list<string>         $seen
     *
     * @return list<string>
     */
    private function propertyPaths(array $schema, array $spec, string $prefix = '', array $seen = []): array
    {
        if (isset($schema['$ref']) && \is_string($schema['$ref'])) {
            if (\in_array($schema['$ref'], $seen, true)) {
                return [];
            }
            $seen[] = $schema['$ref'];
        }

        $schema = $this->resolve($schema, $spec);
        $paths = [];

        foreach ($schema['properties'] ?? [] as $name => $property) {
            $here = $prefix.'/'.$name;
            $paths[] = $here;
            if (\is_array($property)) {
                $paths = [...$paths, ...$this->propertyPaths($property, $spec, $here, $seen)];
            }
        }

        foreach (['items', 'additionalProperties'] as $nested) {
            if (\is_array($schema[$nested] ?? null)) {
                $paths = [...$paths, ...$this->propertyPaths($schema[$nested], $spec, $prefix.'/[]', $seen)];
            }
        }

        foreach (['anyOf', 'oneOf', 'allOf'] as $composite) {
            foreach ($schema[$composite] ?? [] as $branch) {
                if (\is_array($branch)) {
                    $paths = [...$paths, ...$this->propertyPaths($branch, $spec, $prefix, $seen)];
                }
            }
        }

        return $paths;
    }
}
